def coeff_pattern(k, N, L=sp.S.One):
    if k == 0:
        return sp.zeros(0, 0)
    return sp.Matrix([[2*sp.S(k)**2/sp.S(N)**2, 2*L*sp.S(k)/sp.S(N)**2], [2*L*sp.S(k)/sp.S(N)**2, 0]])
